import { escapeHtml, page, photoDataUri } from './common.js';
import { type Hotel, filteredHotels, findHotel } from './data.js';

export interface HotelView {
  city: string | null;
  checkIn: string;
  checkOut: string;
  adults: number;
  rooms: number;
  design: boolean;
  freeCancellation: boolean;
  resultsVisible: boolean;
  sort: string;
  openedHotelId: string | null;
  openedHotelTitle: string | null;
}

function hotelSearchForm(state: HotelView, compact: boolean): string {
  return `<form id="hotel-search-form" class="hotel-search card ${compact ? 'compact' : ''}" autocomplete="off"><div class="hotel-field destination-field"><label for="hotel-city">Destination</label><input id="hotel-city" name="city" aria-label="Destination" role="combobox" aria-controls="city-options" aria-expanded="false" placeholder="Where are you going?" value="${escapeHtml(state.city ?? '')}" required><div id="city-options" role="listbox" class="city-options" hidden></div></div><div class="hotel-field date-field"><label for="hotel-check-in">Check-in</label><input id="hotel-check-in" name="checkIn" aria-label="Check-in" type="date" value="${escapeHtml(state.checkIn)}" min="2026-09-23" max="2027-12-31" required></div><div class="hotel-field date-field"><label for="hotel-check-out">Check-out</label><input id="hotel-check-out" name="checkOut" aria-label="Check-out" type="date" value="${escapeHtml(state.checkOut)}" min="2026-09-24" max="2028-01-01" required></div><div class="hotel-field guests-field"><label>Guests and rooms</label><span><input name="adults" type="number" aria-label="Guests" min="1" max="8" value="${state.adults}"> guests · <input name="rooms" type="number" aria-label="Rooms" min="1" max="4" value="${state.rooms}"> room</span></div><button class="blue-button" type="submit">Search stays</button><div class="quick-filters"><label><input name="design" type="checkbox" ${state.design ? 'checked' : ''}> Design</label><label><input name="freeCancellation" type="checkbox" ${state.freeCancellation ? 'checked' : ''}> Free cancellation</label></div></form><div id="notice" role="alert"></div>`;
}

function hotelCard(hotel: Hotel, runId: string, state: HotelView): string {
  const nights = Math.max(
    1,
    Math.round(
      (Date.parse(state.checkOut) - Date.parse(state.checkIn)) / 86_400_000,
    ),
  );
  return `<article class="hotel-card card"><a class="hotel-image-link" href="/scenario/hotel/${encodeURIComponent(hotel.id)}?runId=${encodeURIComponent(runId)}" data-hotel-id="${escapeHtml(hotel.id)}"><img src="${photoDataUri(hotel.photos[0])}" alt="Illustrative guest accommodation for ${escapeHtml(hotel.name)}"></a><div class="hotel-card-body"><div class="hotel-card-head"><div><h3><a href="/scenario/hotel/${encodeURIComponent(hotel.id)}?runId=${encodeURIComponent(runId)}" data-hotel-id="${escapeHtml(hotel.id)}">${escapeHtml(hotel.name)}</a></h3><p>${'★'.repeat(hotel.stars)} <span>${escapeHtml(hotel.neighborhood)} · ${escapeHtml(hotel.city)}</span></p></div><button class="heart" type="button" aria-label="Save ${escapeHtml(hotel.name)}">♡</button></div><p class="hotel-description">${escapeHtml(hotel.description)}</p><div class="hotel-features">${hotel.tags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join('')}</div><div class="hotel-card-bottom"><span class="rating"><strong>${hotel.score.toFixed(1)}</strong> Wonderful · ${hotel.reviewCount.toLocaleString()} reviews</span><div class="hotel-price"><strong>£${hotel.price}</strong><span>per night · £${hotel.price * nights} total</span><small>Includes taxes & fees</small></div></div></div></article>`;
}

function mapPanel(hotels: readonly Hotel[]): string {
  return `<aside class="map-panel card" aria-label="Map of hotel search area"><div class="map-grid"><div class="water"></div><div class="road r1"></div><div class="road r2"></div><div class="road r3"></div><div class="road r4"></div><span class="map-label l1">BAIXA</span><span class="map-label l2">CHIADO</span><span class="map-label l3">ALFAMA</span>${hotels
    .slice(0, 5)
    .map(
      (hotel, index) =>
        `<span class="price-pin p${index + 1}">£${hotel.price}</span>`,
    )
    .join(
      '',
    )}</div><div class="map-caption">Lisbon center · illustrative map <button type="button" id="map-toggle">Hide map</button></div></aside>`;
}

function sortHotels(items: readonly Hotel[], sort: string): Hotel[] {
  const copy = [...items];
  if (sort === 'price') return copy.sort((a, b) => a.price - b.price);
  if (sort === 'rating') return copy.sort((a, b) => b.score - a.score);
  return copy;
}

export function renderHotelHome(runId: string, state: HotelView): string {
  const cities = `<div class="city-feature"><img src="${photoDataUri('lisbon-cityscape.jpg')}" alt="A view across Lisbon rooftops"><div><strong>Lisbon</strong><span>Colorful streets, historic viewpoints and boutique stays</span></div></div><div class="city-feature"><img src="${photoDataUri('porto-cityscape.jpg')}" alt="Porto and the Douro river"><div><strong>Porto</strong><span>Riverside neighborhoods and design guesthouses</span></div></div>`;
  const body = `<main class="travel-main hotel-page" id="top"><div class="hotel-hero"><div><small>TRAVEL · STAYS</small><h1>Find your place to stay</h1><p>Compare rooms, photos, reviews and flexible booking options in one place.</p></div><img src="${photoDataUri('lisbon-cityscape.jpg')}" alt="Cityscape of Lisbon"></div>${hotelSearchForm(state, false)}<section class="home-recommendations"><h2>Explore places to stay</h2><p class="muted">Hand-picked destinations for your next trip</p><div class="city-features">${cities}</div></section><section class="travel-advice"><h2>Choose a stay that suits you</h2><div><span>⌕ <strong>Compare options</strong><small>Review locations and amenities</small></span><span>▦ <strong>Check your dates</strong><small>See rates for your stay</small></span><span>♡ <strong>Book confidently</strong><small>Compare policies before booking</small></span></div></section></main>`;
  return page('Hotels', 'Hotels', runId, body, css, clientScript(runId));
}

export function renderHotelResults(runId: string, state: HotelView): string {
  const matches = sortHotels(
    filteredHotels(state.city ?? '', state.design, state.freeCancellation),
    state.sort,
  );
  const body = `<main class="travel-main hotel-page results-page" id="top">${hotelSearchForm(state, true)}<div class="hotel-layout"><div class="hotel-results"><div class="results-heading"><div><p class="breadcrumbs">Hotels › ${escapeHtml(state.city ?? '')}</p><h1>Stays in ${escapeHtml(state.city ?? '')}</h1><p class="muted">${matches.length} properties · ${escapeHtml(state.checkIn)} – ${escapeHtml(state.checkOut)} · ${state.adults} guests</p></div><label>Sort by <select id="hotel-sort" aria-label="Sort stays"><option value="recommended" ${state.sort === 'recommended' ? 'selected' : ''}>Recommended</option><option value="price" ${state.sort === 'price' ? 'selected' : ''}>Lowest price</option><option value="rating" ${state.sort === 'rating' ? 'selected' : ''}>Highest rating</option></select></label></div><div class="filter-summary"><span>Filters:</span>${state.design ? '<span class="active-filter">Design ✓</span>' : ''}${state.freeCancellation ? '<span class="active-filter">Free cancellation ✓</span>' : ''}<span>Prices for ${state.rooms} room${state.rooms === 1 ? '' : 's'}</span></div><div class="hotel-list">${matches.map((hotel) => hotelCard(hotel, runId, state)).join('') || '<div class="card empty-results"><h2>No stays match these filters</h2><p>Try a different destination or remove a filter to see more places.</p></div>'}</div></div>${mapPanel(matches)}</div></main>`;
  return page(
    `Stays in ${state.city}`,
    'Hotels',
    runId,
    body,
    css,
    clientScript(runId),
  );
}

function gallery(hotel: Hotel): string {
  return `<div class="hotel-gallery"><button type="button" class="gallery-main" data-photo="0" aria-label="Open photo gallery"><img src="${photoDataUri(hotel.photos[0])}" alt="Illustrative guest room"></button><div>${hotel.photos
    .slice(1, 4)
    .map(
      (name, index) =>
        `<button type="button" data-photo="${index + 1}" aria-label="Open gallery photo ${index + 2}"><img src="${photoDataUri(name)}" alt="Illustrative hotel and neighborhood photo"></button>`,
    )
    .join('')}</div></div>`;
}

export function renderHotelDetail(
  runId: string,
  state: HotelView,
  hotel: Hotel,
): string {
  const back = `/scenario/hotel/results?runId=${encodeURIComponent(runId)}`;
  const body = `<main class="travel-main hotel-page hotel-detail" id="top"><a class="back-link" href="${back}">‹ Back to ${escapeHtml(state.city ?? 'hotel')} results</a><div class="detail-head"><div><p class="breadcrumbs">${escapeHtml(state.city ?? hotel.city)} › ${escapeHtml(hotel.neighborhood)}</p><h1>${escapeHtml(hotel.name)}</h1><p><span class="stars">${'★'.repeat(hotel.stars)}</span> · ${escapeHtml(hotel.neighborhood)}, ${escapeHtml(hotel.city)} · <span class="rating"><strong>${hotel.score.toFixed(1)}</strong> Wonderful (${hotel.reviewCount.toLocaleString()} reviews)</span></p></div><button class="outline-button" type="button" id="share-hotel">Share</button></div>${gallery(hotel)}<nav class="detail-tabs" aria-label="Hotel sections"><a href="#overview">Overview</a><a href="#room-rates">Prices</a><a href="#photos">Photos</a><a href="#reviews">Reviews</a><a href="#policies">Policies</a></nav><div class="detail-layout"><div><section id="overview"><h2>About ${escapeHtml(hotel.name)}</h2><p>${escapeHtml(hotel.description)} From this base you can explore local restaurants, galleries and viewpoints on foot.</p><div class="amenities"><h3>Popular amenities</h3><div>${hotel.amenities.map((amenity) => `<span>✓ ${escapeHtml(amenity)}</span>`).join('')}</div></div><div class="location-card card"><strong>Location</strong><p>${escapeHtml(hotel.neighborhood)}, ${escapeHtml(hotel.city)} · Near transit and neighborhood cafés</p><p>Walkability, sights and restaurants are a short distance away.</p></div></section><section id="room-rates"><h2>Rooms and rates</h2><p class="muted">${escapeHtml(state.checkIn)} – ${escapeHtml(state.checkOut)} · ${state.adults} guests · ${state.rooms} room${state.rooms === 1 ? '' : 's'}</p><div class="room-card card"><img src="${photoDataUri(hotel.photos[1] ?? hotel.photos[0])}" alt="Illustrative guest room"><div><h3>Deluxe double room</h3><p>1 queen bed · 2 guests · Wi-Fi · Air conditioning</p><p class="policy-good">${hotel.freeCancellation ? 'Free cancellation until 48 hours before check-in' : 'Non-refundable rate'}</p></div><div><strong>£${hotel.price}</strong><span>per night</span><button type="button" class="blue-button view-rate">View rate</button></div></div><div class="room-card card"><img src="${photoDataUri(hotel.photos[3] ?? hotel.photos[1] ?? hotel.photos[0])}" alt="Illustrative room interior"><div><h3>Superior room with city view</h3><p>1 king bed · 2 guests · City view · Breakfast option</p><p class="policy-good">${hotel.freeCancellation ? 'Free cancellation available' : 'Terms vary by rate'}</p></div><div><strong>£${hotel.price + 38}</strong><span>per night</span><button type="button" class="blue-button view-rate">View rate</button></div></div></section><section id="photos"><h2>Photos</h2><div class="photo-grid">${hotel.photos.map((name, index) => `<button type="button" data-photo="${index}" aria-label="Open gallery photo ${index + 1}"><img src="${photoDataUri(name)}" alt="Illustrative hotel or neighborhood photograph"></button>`).join('')}</div></section><section id="reviews"><h2>Guest reviews</h2><div class="review-summary"><strong>${hotel.score.toFixed(1)}</strong><div><b>Wonderful</b><span>Based on ${hotel.reviewCount.toLocaleString()} sample reviews</span></div></div><div class="review card"><strong>“A thoughtful place to stay”</strong><p>Comfortable rooms and a convenient base for exploring the city. We especially enjoyed the calm courtyard after a day on foot.</p><small>Traveler review · sample fixture content</small></div><div class="review card"><strong>“Well located and welcoming”</strong><p>The neighborhood made it easy to explore nearby cafés and galleries. Staff were helpful with local suggestions.</p><small>Traveler review · sample fixture content</small></div></section><section id="policies"><h2>Property policies</h2><dl><dt>Check-in</dt><dd>From 3:00 PM</dd><dt>Check-out</dt><dd>Until 11:00 AM</dd><dt>Cancellation</dt><dd>${hotel.freeCancellation ? 'Flexible options available; check the selected rate.' : 'Selected rates may be non-refundable.'}</dd><dt>Pets</dt><dd>Contact the property before arrival</dd></dl></section></div><aside class="detail-book card"><strong>From £${hotel.price}</strong><span>per night · includes taxes & fees</span><p>${escapeHtml(state.checkIn)} – ${escapeHtml(state.checkOut)}<br>${state.adults} guests · ${state.rooms} room</p><a class="blue-button" href="#room-rates">See room options</a><small>Compare policies and room features before selecting a rate.</small></aside></div><div id="photo-modal" class="photo-modal" role="dialog" aria-label="Hotel photo gallery" hidden><button type="button" id="close-gallery" aria-label="Close gallery">✕</button><button type="button" id="previous-photo" aria-label="Previous photo">‹</button><img id="modal-photo" alt="Expanded illustrative hotel photo"><button type="button" id="next-photo" aria-label="Next photo">›</button><span id="photo-count"></span></div></main>`;
  return page(
    hotel.name,
    'Hotels',
    runId,
    body,
    css,
    clientScript(runId, hotel),
  );
}

function clientScript(runId: string, hotel?: Hotel): string {
  return `
const RUN_ID=${JSON.stringify(runId)},API='/api/travel/'+encodeURIComponent(RUN_ID)+'/';
const q=(selector)=>document.querySelector(selector);
const notice=(message)=>{const box=q('#notice')||document.createElement('div');box.id='notice';box.role='alert';box.textContent=message;box.style.display='block';if(!box.parentNode)q('.travel-main').prepend(box);};
async function request(path,payload){const response=await fetch(API+path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data;}
const city=q('#hotel-city'),options=q('#city-options');
if(city){let timer;city.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{const term=city.value.trim();if(!term){options.hidden=true;return;}try{const response=await fetch(API+'hotels/destinations?q='+encodeURIComponent(term));const data=await response.json();options.replaceChildren();for(const place of data.destinations){const button=document.createElement('button');button.type='button';button.innerHTML='<span>⌖</span><span><strong></strong><small></small></span>';button.querySelector('strong').textContent=place.city;button.querySelector('small').textContent=place.country;button.addEventListener('click',()=>{city.value=place.city;options.hidden=true;city.setAttribute('aria-expanded','false');});options.append(button);}options.hidden=data.destinations.length===0;city.setAttribute('aria-expanded',String(!options.hidden));}catch{options.hidden=true;}},100);});city.addEventListener('keydown',(event)=>{if(event.key==='Escape')options.hidden=true;if(event.key==='ArrowDown'&&!options.hidden){event.preventDefault();options.querySelector('button')?.focus();}});}
document.addEventListener('click',(event)=>{if(options&&!event.target.closest('.destination-field'))options.hidden=true;});
q('#hotel-search-form')?.addEventListener('submit',async(event)=>{event.preventDefault();const form=event.currentTarget;const body={city:form.elements.city.value.trim(),checkIn:form.elements.checkIn.value,checkOut:form.elements.checkOut.value,adults:Number(form.elements.adults.value),rooms:Number(form.elements.rooms.value),design:form.elements.design.checked,freeCancellation:form.elements.freeCancellation.checked};const button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Finding stays…';try{await request('hotels/search',body);location.assign('/scenario/hotel/results?runId='+encodeURIComponent(RUN_ID));}catch(error){notice(String(error));button.disabled=false;button.textContent='Search stays';}});
q('#hotel-sort')?.addEventListener('change',async(event)=>{try{await request('hotels/sort',{sort:event.target.value});location.reload();}catch(error){notice(String(error));}});
q('#map-toggle')?.addEventListener('click',()=>{const map=q('.map-grid');map.hidden=!map.hidden;q('#map-toggle').textContent=map.hidden?'Show map':'Hide map';});
document.addEventListener('click',async(event)=>{const link=event.target.closest('a[data-hotel-id]');if(!link||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||event.button!==0)return;event.preventDefault();try{await request('hotels/open',{hotelId:link.dataset.hotelId});location.assign(link.href);}catch(error){notice(String(error));}});
for(const button of document.querySelectorAll('.heart'))button.addEventListener('click',()=>{button.textContent=button.textContent==='♡'?'♥':'♡';});
const images=${JSON.stringify(hotel?.photos.map(photoDataUri) ?? [])};let photoIndex=0;
function showPhoto(index){const modal=q('#photo-modal');if(!modal)return;photoIndex=(index+images.length)%images.length;q('#modal-photo').src=images[photoIndex];q('#photo-count').textContent=(photoIndex+1)+' / '+images.length;modal.hidden=false;}
for(const button of document.querySelectorAll('[data-photo]'))button.addEventListener('click',()=>showPhoto(Number(button.dataset.photo)));
q('#close-gallery')?.addEventListener('click',()=>q('#photo-modal').hidden=true);q('#previous-photo')?.addEventListener('click',()=>showPhoto(photoIndex-1));q('#next-photo')?.addEventListener('click',()=>showPhoto(photoIndex+1));
q('#share-hotel')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);notice('Link copied to clipboard.');}catch{notice('Share this page using the URL in your address bar.');}});
for(const button of document.querySelectorAll('.view-rate'))button.addEventListener('click',()=>notice('This sample listing shows room features and policy details; live booking is not connected.'));
document.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&q('#photo-modal'))q('#photo-modal').hidden=true;});
`;
}

